// Verify the request really came from your auth service.
//
// An n8n webhook is a URL, and URLs leak — browser history, a screenshot, an
// exported workflow. Without this check, whoever finds it can send email from
// your domain with content of their choosing.
//
// Set BASIVO_WEBHOOK_SECRET in n8n's environment to the EMAIL_WEBHOOK_SECRET
// from your service's .env. Never paste the secret into this node.

const crypto = require('crypto');

const secret = $env.BASIVO_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('BASIVO_WEBHOOK_SECRET is not set in n8n');
}

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-basivo-signature'] || '';
const timestamp = headers['x-basivo-timestamp'] || '';

if (!signature || !timestamp) {
  throw new Error('Unsigned request');
}

// Bound replay: reject anything older than five minutes.
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) {
  throw new Error('Stale request');
}

// Prefer the raw body, which is exactly what was signed. n8n exposes it in
// different shapes depending on version and settings, so try each in turn.
let raw;
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64');
} else if (Buffer.isBuffer(item.json.body)) {
  raw = item.json.body;
} else if (typeof item.json.body === 'string') {
  raw = Buffer.from(item.json.body, 'utf8');
} else {
  // Fallback: rebuild the canonical form. The sender serialises with sorted
  // keys, no spaces and real UTF-8, so this reproduces the signed bytes.
  const canonical = (v) => {
    if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']';
    if (v && typeof v === 'object') {
      return '{' + Object.keys(v).sort()
        .map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
    }
    return JSON.stringify(v);
  };
  raw = Buffer.from(canonical(item.json.body), 'utf8');
}

const expected = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(Buffer.concat([Buffer.from(timestamp + '.', 'utf8'), raw]))
  .digest('hex');

// timingSafeEqual, not ===. A plain comparison returns at the first wrong
// byte, and that timing difference is enough to recover a signature.
const a = Buffer.from(signature);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Bad signature');
}

// Hand the parsed email on as the item body.
const email = typeof item.json.body === 'string'
  ? JSON.parse(item.json.body)
  : (Buffer.isBuffer(item.json.body) ? JSON.parse(item.json.body.toString('utf8')) : item.json.body);

return [{ json: email }];
